module freq_div (
	input CLK_in, RST,
	output CLK_50, CLK_10, CLK_1
);
	reg CLK_50_reg, CLK_10_reg, CLK_1_reg;

	// CLK_50 generation
	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			CLK_50_reg <= 1'b0;
		end
		else begin
			CLK_50_reg <= ~CLK_50_reg;
		end
	end

	// CLK_10 generation
	reg [3:0] cnt_10;
	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			cnt_10 <= 4'b0;
			CLK_10_reg <= 1'b0;
		end
		else if(cnt_10 == 4'd9) begin
			cnt_10 <= 4'b0;
			CLK_10_reg <= ~CLK_10_reg;
		end
		else begin
			cnt_10 <= cnt_10 + 1;
		end
	end

	// CLK_1 generation
	reg [6:0] cnt_100;
	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			cnt_100 <= 7'b0;
			CLK_1_reg <= 1'b0;
		end
		else if(cnt_100 == 7'd99) begin
			cnt_100 <= 7'b0;
			CLK_1_reg <= ~CLK_1_reg;
		end
		else begin
			cnt_100 <= cnt_100 + 1;
		end
	end

	assign CLK_50 = CLK_50_reg;
	assign CLK_10 = CLK_10_reg;
	assign CLK_1 = CLK_1_reg;

endmodule
